import {validate,REVISION} from './engine.mjs';
const $=id=>document.getElementById(id), chart=$('chart'), ctx=chart.getContext('2d');
let run=null,pinned=null,frame=0,playing=false,lastTick=0,worker=null,busy=false,research=false;
function params(){return validate({n:+$('cells').value,a:+$('velocity').value,D:+$('diffusion').value,duration:+$('duration').value,cfl:+$('cfl').value,profile:+$('profile').value});}
function labels(){$('velocityOut').value=(+$('velocity').value).toFixed(2);$('diffusionOut').value=(+$('diffusion').value).toFixed(3);}
function mode(value){research=value;$('researchControls').hidden=!value;$('researchContent').hidden=!value;$('learnContent').hidden=value;for(const id of ['learn','research']){$(id).classList.toggle('active',(id==='research')===value);$(id).setAttribute('aria-pressed',String((id==='research')===value));}document.querySelector('h1').innerHTML=value?'Explore. Measure.<br><span>Reproduce.</span>':'A little motion.<br><span>A lot to discover.</span>';document.querySelector('.intro').textContent=value?'A browser workspace for 1D advection–diffusion experiments.':'Move a pulse. Watch it spread. Understand the equation.';}
$('learn').onclick=()=>mode(false);$('research').onclick=()=>mode(true);
function stop(){playing=false;$('play').textContent='Play';$('play').setAttribute('aria-label','Play simulation');}
function updateControls(){labels();stop();$('status').textContent=busy?'Parameters changed. Run again to replace the active calculation.':'Parameters changed. Run experiment to apply.';}
for(const id of ['profile','velocity','diffusion','cells','duration','cfl'])$(id).addEventListener('input',updateControls);
function mass(a){return a.reduce((x,y)=>x+y,0)/a.length;}
function errorToExact(r,index){if(r.params.profile!==1)return null;const {n,a,D}=r.params,t=r.times[index];const sinc=Math.sin(Math.PI/n)/(Math.PI/n);return Math.sqrt(r.frames[index].reduce((s,u,i)=>s+(u-(.5+.4*sinc*Math.exp(-4*Math.PI*Math.PI*D*t)*Math.sin(2*Math.PI*((i+.5)/n-a*t))))**2,0)/n);}
function showInfo(){if(!run)return;const p=run.params;const error=errorToExact(run,100);$('runInfo').textContent=`${p.n} cells · v = ${p.a} · D = ${p.D} · end time = ${p.duration} · safety = ${p.cfl}\n${run.steps.toLocaleString()} steps · max Δt = ${run.dt.toExponential(3)} · ${run.elapsed.toFixed(1)} ms compute time\n${error===null?'Select the sine wave to compare with its exact solution.':`Final L₂ error vs exact cell averages: ${error.toExponential(4)}`}\nSource ${REVISION.slice(0,12)} · custom periodic SSP-RK2 driver${pinned?`\nPinned: ${pinned.params.n} cells · v = ${pinned.params.a} · D = ${pinned.params.D} · end time = ${pinned.params.duration}`:''}`;$('runInfo').style.whiteSpace='pre-line';}
function draw(){
 const box=chart.getBoundingClientRect(),w=box.width,h=box.height,dpr=window.devicePixelRatio||1;if(!w||!h)return;chart.width=Math.round(w*dpr);chart.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);
 const pad={l:43,r:14,t:32,b:37},cw=w-pad.l-pad.r,ch=h-pad.t-pad.b;const xx=x=>pad.l+x*cw,yy=y=>pad.t+ch*(1-y/1.1);
 ctx.font='12px "DM Sans",sans-serif';ctx.fillStyle='#99a9bc';ctx.fillText('concentration u',pad.l,15);ctx.strokeStyle='#273444';ctx.lineWidth=1;
 for(let i=0;i<=5;i++){const val=i/5,y=yy(val);ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(w-pad.r,y);ctx.stroke();ctx.fillText(val.toFixed(1),10,y+4);const x=xx(val);ctx.fillText(val.toFixed(1),x-8,h-16);}
 ctx.textAlign='right';ctx.fillText('position x',w-pad.r,h-1);ctx.textAlign='left';
 if(!run){ctx.fillText('Preparing your first experiment…',pad.l+10,h/2);return;}
 const values=run.frames[frame];
 function path(arr,color,dash,fill=false){ctx.beginPath();for(let i=0;i<arr.length;i++){const x=xx((i+.5)/arr.length),y=yy(arr[i]);if(!i)ctx.moveTo(x,y);else ctx.lineTo(x,y);}ctx.lineWidth=2;ctx.strokeStyle=color;ctx.setLineDash(dash);ctx.stroke();if(fill){ctx.lineTo(xx(1-.5/arr.length),yy(0));ctx.lineTo(xx(.5/arr.length),yy(0));ctx.closePath();const g=ctx.createLinearGradient(0,pad.t,0,yy(0));g.addColorStop(0,'#5ee4d02a');g.addColorStop(1,'#5ee4d003');ctx.fillStyle=g;ctx.fill();}ctx.setLineDash([]);}
 path(run.frames[0],'#8393a6',[4,5]);path(values,'#5ee4d0',[],true);
 const t=run.times[frame],canCompare=pinned&&t<=pinned.params.duration+1e-10;$('compareLegend').hidden=!canCompare;
 if(canCompare){const z=Math.min(100,t/pinned.params.duration*100),lo=Math.floor(z),hi=Math.min(100,lo+1),f=z-lo;const a=pinned.frames[lo].map((v,i)=>v*(1-f)+pinned.frames[hi][i]*f);path(a,'#ffb06b',[7,3]);}
 $('time').value=`t = ${t.toFixed(3)}`;$('scrub').value=frame;$('peak').textContent=Math.max(...values).toFixed(4);$('mass').textContent=Math.abs(mass(values)-mass(run.frames[0])).toExponential(1);$('third').textContent=run.params.n;
 chart.setAttribute('aria-label',`Concentration against position at time ${t.toFixed(3)}. Peak ${Math.max(...values).toFixed(4)}. Absolute mass drift ${Math.abs(mass(values)-mass(run.frames[0])).toExponential(1)}.`);
}
new ResizeObserver(draw).observe(chart);
async function runExperiment(){
 let p;try{p=params();}catch(e){$('status').textContent=e.message;throw e;}
 stop();if(worker)worker.terminate();busy=true;$('run').disabled=true;$('run').textContent='Computing…';$('status').textContent='Running original C kernels in your browser.';
 return new Promise((resolve,reject)=>{worker=new Worker('./worker.js',{type:'module'});worker.onmessage=({data})=>{busy=false;$('run').disabled=false;$('run').textContent='Run experiment';if(data.error){$('status').textContent=data.error;reject(Error(data.error));return;}run=data.result;frame=0;$('engine').textContent='C kernels · ready';$('status').textContent='Complete. Scrub the timeline or press Play.';for(const id of ['play','scrub','pin','csv','json'])$(id).disabled=false;showInfo();draw();resolve({cells:run.params.n,steps:run.steps,duration:run.params.duration,finalL2Error:errorToExact(run,100)});};worker.onerror=()=>{busy=false;$('run').disabled=false;$('run').textContent='Retry experiment';$('status').textContent='Could not load the solver. Check your connection and retry.';reject(Error('Solver could not load.'));};worker.postMessage(p);});
}
$('run').onclick=()=>runExperiment().catch(()=>{});
$('play').onclick=()=>{if(playing){stop();return;}if(frame===100)frame=0;playing=true;lastTick=0;$('play').textContent='Pause';$('play').setAttribute('aria-label','Pause simulation');requestAnimationFrame(animate);};
function animate(timestamp){if(!playing)return;if(!lastTick)lastTick=timestamp;if(timestamp-lastTick>=50){frame=Math.min(100,frame+Math.floor((timestamp-lastTick)/50));lastTick=timestamp;draw();if(frame===100){stop();return;}}requestAnimationFrame(animate);}
$('scrub').oninput=()=>{stop();frame=+$('scrub').value;draw();};
for(const button of document.querySelectorAll('[data-preset]'))button.onclick=()=>{const presets={transport:[.8,.001],spread:[0,.015],reverse:[-.7,.003]};const [a,D]=presets[button.dataset.preset];$('velocity').value=a;$('diffusion').value=D;$('profile').value='0';labels();runExperiment().then(()=>$('play').click()).catch(()=>{});};
$('pin').onclick=()=>{if(pinned){pinned=null;$('pin').textContent='Pin run';}else{pinned=run;$('pin').textContent='Clear pinned run';}showInfo();draw();};
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('csv').onclick=()=>{if(!run)return;let s='time,x,concentration\n';for(let f=0;f<run.frames.length;f++)for(let i=0;i<run.params.n;i++)s+=`${run.times[f]},${(i+.5)/run.params.n},${run.frames[f][i]}\n`;download('transport-run.csv',s,'text/csv');};
$('json').onclick=()=>{if(!run)return;download('transport-run.json',JSON.stringify({schemaVersion:1,parameters:run.params,source:{repository:'https://github.com/lanyonai/AdvectionDiffusion',revision:REVISION,file:'implementations/advection_diffusion_iso_1d.c'},method:'minmod finite-volume, Rusanov advection, centered diffusion, SSP-RK2',domain:[0,1],boundary:'periodic',frameCount:101,initialCellAverageQuadrature:16,driverVerified:false},null,2),'application/json');};
labels();runExperiment().catch(()=>{});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'run_transport_experiment',title:'Run transport experiment',description:'Configure and run the visible advection–diffusion experiment, then return diagnostics.',inputSchema:{type:'object',properties:{n:{type:'integer',enum:[64,128,256,512]},a:{type:'number',minimum:-1,maximum:1},D:{type:'number',minimum:.001,maximum:.02},duration:{type:'number',minimum:.1,maximum:3},cfl:{type:'number',minimum:.1,maximum:.45},profile:{type:'integer',enum:[0,1,2]}},required:['n','a','D','duration','cfl','profile'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async input=>{validate(input);if(busy)throw Error('A simulation is already running.');const mapping={n:'cells',a:'velocity',D:'diffusion',duration:'duration',cfl:'cfl',profile:'profile'};for(const [key,id] of Object.entries(mapping))$(id).value=input[key];labels();mode(true);return runExperiment();}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
